// ---- Input and output (no need to change anything below) ----

struct Node *newNode(int value) {
    struct Node *node = malloc(sizeof(struct Node));
    node->value = value;
    node->left = NULL;
    node->right = NULL;
    return node;
}

// Builds a tree from level-order tokens ("null" means no node)
struct Node *readTree(char tokens[][8], int count) {
    if (count == 0 || strcmp(tokens[0], "null") == 0) {
        return NULL;
    }
    struct Node **queue = malloc(count * sizeof(struct Node *));
    int head = 0, tail = 0, next = 1;
    struct Node *root = newNode(atoi(tokens[0]));
    queue[tail++] = root;
    while (head < tail && next < count) {
        struct Node *node = queue[head++];
        if (next < count && strcmp(tokens[next], "null") != 0) {
            node->left = newNode(atoi(tokens[next]));
            queue[tail++] = node->left;
        }
        next++;
        if (next < count && strcmp(tokens[next], "null") != 0) {
            node->right = newNode(atoi(tokens[next]));
            queue[tail++] = node->right;
        }
        next++;
    }
    free(queue);
    return root;
}

// Prints a tree in the same level-order format, without trailing nulls
void printTree(struct Node *root) {
    struct Node **queue = malloc(MAX_TOKENS * 2 * sizeof(struct Node *));
    int head = 0, tail = 0, last = 0;
    queue[tail++] = root;
    while (head < tail) {
        struct Node *node = queue[head++];
        if (node != NULL) {
            last = head;
            queue[tail++] = node->left;
            queue[tail++] = node->right;
        }
    }
    for (int i = 0; i < last; i++) {
        if (i > 0) {
            printf(" ");
        }
        if (queue[i] == NULL) {
            printf("null");
        } else {
            printf("%d", queue[i]->value);
        }
    }
    printf("\n");
    free(queue);
}

int main(void) {
    static char tokens[MAX_TOKENS][8];
    int count = 0;
    while (count < MAX_TOKENS && scanf("%7s", tokens[count]) == 1) {
        count++;
    }

    struct Node *root = readTree(tokens, count);
    char *data = serialize(root);
    printTree(deserialize(data == NULL ? "" : data));
    free(data);
    return 0;
}

